const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const str = buf.toString('utf-8');
// Search for 'priya' context and calendar info
const idx = str.indexOf('priya');
if (idx >= 0) {
  // Look for date/calendar references near priya
  let matches = [...str.matchAll(/priya[^]*?\.ics/gi)];
  matches.forEach(m => console.log(m[0].substring(0, 300)));
}
// Also look for 'today' or current date references
let dateMatches = [...str.matchAll(/today|current.date|202[0-9]-[0-9]{2}-[0-9]{2}|202[0-9][01][0-9][0-3][0-9]/gi)];
dateMatches.slice(0, 20).forEach(m => {
  const s = Math.max(0, m.index - 100);
  const e = Math.min(str.length, m.index + 100);
  console.log('---', str.substring(s, e).replace(/[^\x20-\x7E\n]/g, ' '));
});
"

